INSERT INTO `service_categories` (`category_id`, `category_name`, `category_slug`, `category_heading`, `category_description`, `category_order`, `category_status`, `category_added`, `category_updated`) VALUES (1, 'Nails', 'nails', NULL, 'Manicure, gel, extensions and hand-painted nail art — what we do most.', 1, 'Enable', NOW(), NOW());
INSERT INTO `service_categories` (`category_id`, `category_name`, `category_slug`, `category_heading`, `category_description`, `category_order`, `category_status`, `category_added`, `category_updated`) VALUES (2, 'Hair', 'hair', NULL, 'Cuts, styling, colour and care, booked on their own or with nails.', 2, 'Enable', NOW(), NOW());
INSERT INTO `service_categories` (`category_id`, `category_name`, `category_slug`, `category_heading`, `category_description`, `category_order`, `category_status`, `category_added`, `category_updated`) VALUES (3, 'Beauty', 'beauty', NULL, 'Facials, makeup, brows and waxing in the same relaxed studio.', 3, 'Enable', NOW(), NOW());
INSERT INTO `services` (`service_id`, `service_category_id`, `service_name`, `service_slug`, `service_summary`, `service_description`, `service_price_from`, `service_price_suffix`, `service_duration_label`, `service_duration_minutes`, `service_card_image`, `service_hero_image`, `service_included`, `service_before_visit`, `service_aftercare`, `service_featured`, `service_show_shapes`, `page_title`, `meta_description`, `robots_index`, `robots_follow`, `og_title`, `og_description`, `og_image`, `service_order`, `service_status`, `service_added`, `service_updated`) VALUES (1, 1, 'Manicure', 'manicure', 'Classic or combined manicure — cuticle work, shaping and a smooth, even finish. Choose a natural look or a colour you love.', '<p>Our most-booked service and the base everything else is built on. We tidy the cuticles, shape the free edge to the length you like, and finish with a buff or a colour of your choosing.</p>', '80', '', '60 min', 60, 'efcd7c7abacc9df320dd2588d5c63d60.jpg', 'efcd7c7abacc9df320dd2588d5c63d60.jpg', 'Cuticle care and nail shaping\nLight buff and surface smoothing\nRegular polish or a bare, natural finish\nHand cream and a short hand massage', 'Come with clean, product-free nails if you can\nBring a colour or photo if you already have one in mind', 'Give regular polish a couple of hours before anything rough\nCuticle oil daily keeps the finish looking fresh for longer', 1, 1, 'Manicure | Blossom Ewa Mazur', 'Classic or combined manicure — cuticle work, shaping and a smooth, even finish. Choose a natural look or a colour you love. From 80 zł at Blossom Ewa Mazur in Gorlice.', 1, 1, '', '', NULL, 1, 'Enable', NOW(), NOW());
INSERT INTO `services` (`service_id`, `service_category_id`, `service_name`, `service_slug`, `service_summary`, `service_description`, `service_price_from`, `service_price_suffix`, `service_duration_label`, `service_duration_minutes`, `service_card_image`, `service_hero_image`, `service_included`, `service_before_visit`, `service_aftercare`, `service_featured`, `service_show_shapes`, `page_title`, `meta_description`, `robots_index`, `robots_follow`, `og_title`, `og_description`, `og_image`, `service_order`, `service_status`, `service_added`, `service_updated`) VALUES (2, 1, 'Gel Manicure', 'gel-manicure', 'A full manicure finished in gel colour — long-wearing, glossy, and kind to the nail underneath.', '<p>The same careful prep as a classic manicure, finished with gel colour cured under lamp. It keeps its shine far longer than regular polish and is the one most clients come back for.</p>', '120', '', '75 min', 75, 'd0ce28377ff9be4b76002f3776eb547f.jpg', 'd0ce28377ff9be4b76002f3776eb547f.jpg', 'Full manicure and cuticle preparation\nGel base, colour and top coat\nShaping to the length you prefer\nRemoval of existing gel where needed', 'Let us know at booking if you have gel on that needs removing', 'Cuticle oil daily keeps the gel flexible and the skin comfortable\nCome back for removal rather than peeling it off — peeling takes the top layer of the nail with it', 1, 1, 'Gel Manicure | Blossom Ewa Mazur', 'A full manicure finished in gel colour — long-wearing, glossy, and kind to the nail underneath. From 120 zł at Blossom Ewa Mazur in Gorlice.', 1, 1, '', '', NULL, 2, 'Enable', NOW(), NOW());
INSERT INTO `services` (`service_id`, `service_category_id`, `service_name`, `service_slug`, `service_summary`, `service_description`, `service_price_from`, `service_price_suffix`, `service_duration_label`, `service_duration_minutes`, `service_card_image`, `service_hero_image`, `service_included`, `service_before_visit`, `service_aftercare`, `service_featured`, `service_show_shapes`, `page_title`, `meta_description`, `robots_index`, `robots_follow`, `og_title`, `og_description`, `og_image`, `service_order`, `service_status`, `service_added`, `service_updated`) VALUES (3, 1, 'Nail Art', 'nail-art', 'Hand-painted designs, from a single fine line to a full set. Bring a photo you like or plan it together at the table.', '<p>Everything here is painted by hand, one nail at a time. Minimal lines, French variations, chrome, marble or something seasonal — we work out the design with you before anything is painted.</p>', '20', '/ nail', '+30 min', 30, '603a796a22930ebed85292ca424ef10b.jpg', '603a796a22930ebed85292ca424ef10b.jpg', 'Design planned with you before we start\nHand-painted detail, priced per nail\nChoice of finish — matte, gloss, chrome or pearl\nAdded to any manicure or gel service', 'Save a few reference photos — screenshots are perfect\nBook a little extra time if you want art on every nail', 'A gloss or matte top coat refresh keeps the design sharp', 1, 1, 'Nail Art | Blossom Ewa Mazur', 'Hand-painted designs, from a single fine line to a full set. Bring a photo you like or plan it together at the table. From 20 zł / nail at Blossom Ewa Mazur in Gorlice.', 1, 1, '', '', NULL, 3, 'Enable', NOW(), NOW());
INSERT INTO `services` (`service_id`, `service_category_id`, `service_name`, `service_slug`, `service_summary`, `service_description`, `service_price_from`, `service_price_suffix`, `service_duration_label`, `service_duration_minutes`, `service_card_image`, `service_hero_image`, `service_included`, `service_before_visit`, `service_aftercare`, `service_featured`, `service_show_shapes`, `page_title`, `meta_description`, `robots_index`, `robots_follow`, `og_title`, `og_description`, `og_image`, `service_order`, `service_status`, `service_added`, `service_updated`) VALUES (4, 1, 'Nail Extensions', 'nail-extensions', 'Gel extensions in the length and shape that suit your hands, with refills when you need them.', '<p>Builder gel and extensions for extra length, shaped to almond, square, oval or coffin. We talk through what will actually be comfortable for your hands and how you use them before choosing a length.</p>', '140', '', '90–120 min', 120, '9807e290d001a485b35a9db646a2489b.jpg', '9807e290d001a485b35a9db646a2489b.jpg', 'Full preparation and cuticle work\nGel extension to your chosen length and shape\nColour or a natural finish\nShape advice for your nail bed', 'Allow a little longer than a standard appointment\nThink about the length you can live with day to day', 'Refills every three to four weeks keep the shape balanced\nBook removal with us rather than taking them off at home', 1, 1, 'Nail Extensions | Blossom Ewa Mazur', 'Gel extensions in the length and shape that suit your hands, with refills when you need them. From 140 zł at Blossom Ewa Mazur in Gorlice.', 1, 1, '', '', NULL, 4, 'Enable', NOW(), NOW());
INSERT INTO `services` (`service_id`, `service_category_id`, `service_name`, `service_slug`, `service_summary`, `service_description`, `service_price_from`, `service_price_suffix`, `service_duration_label`, `service_duration_minutes`, `service_card_image`, `service_hero_image`, `service_included`, `service_before_visit`, `service_aftercare`, `service_featured`, `service_show_shapes`, `page_title`, `meta_description`, `robots_index`, `robots_follow`, `og_title`, `og_description`, `og_image`, `service_order`, `service_status`, `service_added`, `service_updated`) VALUES (5, 1, 'Nail Styling', 'nail-styling', 'Shape, length and finish planned around your hands — the consultation that makes everything else fit.', '<p>A sit-down about what actually suits you: nail shape, length, colour direction and finish. Useful before a first gel set, an event, or if you have never quite settled on a shape.</p>', '60', '', '30 min', 30, '71cb0c0e9b87f7f7c318eef6faac7f56.jpg', '71cb0c0e9b87f7f7c318eef6faac7f56.jpg', 'Shape and length consultation\nColour and finish direction\nShade matching against your skin tone\nA plan for your next few appointments', 'Bring any photos of sets you have liked or disliked', '', 0, 1, 'Nail Styling | Blossom Ewa Mazur', 'Shape, length and finish planned around your hands — the consultation that makes everything else fit. From 60 zł at Blossom Ewa Mazur in Gorlice.', 1, 1, '', '', NULL, 5, 'Enable', NOW(), NOW());
INSERT INTO `services` (`service_id`, `service_category_id`, `service_name`, `service_slug`, `service_summary`, `service_description`, `service_price_from`, `service_price_suffix`, `service_duration_label`, `service_duration_minutes`, `service_card_image`, `service_hero_image`, `service_included`, `service_before_visit`, `service_aftercare`, `service_featured`, `service_show_shapes`, `page_title`, `meta_description`, `robots_index`, `robots_follow`, `og_title`, `og_description`, `og_image`, `service_order`, `service_status`, `service_added`, `service_updated`) VALUES (6, 1, 'Nail Care & Repair', 'nail-care', 'Gentle care for weak, peeling or bitten nails, plus hand care and advice for between visits.', '<p>For nails that need a bit of looking after rather than covering up. We keep the work gentle, tidy what is there, and talk through a simple routine to follow at home.</p>', '70', '', '45 min', 45, 'd6b02bbdc27e2d8704f77b07e40854d6.jpg', 'd6b02bbdc27e2d8704f77b07e40854d6.jpg', 'Gentle shaping and cuticle care\nSingle-nail repair where possible\nNourishing treatment and hand care\nA simple at-home routine to follow', 'Come as you are — there is nothing to tidy up beforehand', 'Cuticle oil daily is the single most useful habit\nGive the nails a few weeks between gel sets if they feel weak', 0, 1, 'Nail Care & Repair | Blossom Ewa Mazur', 'Gentle care for weak, peeling or bitten nails, plus hand care and advice for between visits. From 70 zł at Blossom Ewa Mazur in Gorlice.', 1, 1, '', '', NULL, 6, 'Enable', NOW(), NOW());
INSERT INTO `services` (`service_id`, `service_category_id`, `service_name`, `service_slug`, `service_summary`, `service_description`, `service_price_from`, `service_price_suffix`, `service_duration_label`, `service_duration_minutes`, `service_card_image`, `service_hero_image`, `service_included`, `service_before_visit`, `service_aftercare`, `service_featured`, `service_show_shapes`, `page_title`, `meta_description`, `robots_index`, `robots_follow`, `og_title`, `og_description`, `og_image`, `service_order`, `service_status`, `service_added`, `service_updated`) VALUES (7, 2, 'Haircut', 'haircut', 'A cut shaped to how you actually wear your hair day to day.', '<p>We start by talking about how you style your hair at home, then cut to suit that rather than to suit a photo you will never recreate.</p>', '90', '', '60 min', 60, '97855de9edb5b83acd7907627b0d29fe.jpg', '97855de9edb5b83acd7907627b0d29fe.jpg', 'Consultation\nWash and cut\nFinish and style', '', '', 0, 0, 'Haircut | Blossom Ewa Mazur', 'A cut shaped to how you actually wear your hair day to day. From 90 zł at Blossom Ewa Mazur in Gorlice.', 1, 1, '', '', NULL, 7, 'Enable', NOW(), NOW());
INSERT INTO `services` (`service_id`, `service_category_id`, `service_name`, `service_slug`, `service_summary`, `service_description`, `service_price_from`, `service_price_suffix`, `service_duration_label`, `service_duration_minutes`, `service_card_image`, `service_hero_image`, `service_included`, `service_before_visit`, `service_aftercare`, `service_featured`, `service_show_shapes`, `page_title`, `meta_description`, `robots_index`, `robots_follow`, `og_title`, `og_description`, `og_image`, `service_order`, `service_status`, `service_added`, `service_updated`) VALUES (8, 2, 'Hair Styling', 'hair-styling', 'Blow-dry, waves or an occasion style for weddings and events.', '<p>Styling for a specific day — a birthday, a wedding, or just because. Tell us what you are dressing for and we will work to that.</p>', '80', '', '45 min', 45, 'dfe5cbd36483eb4bbd49abd88080efa1.jpg', 'dfe5cbd36483eb4bbd49abd88080efa1.jpg', 'Wash and prep\nBlow-dry or set\nFinish that holds all day', '', '', 0, 0, 'Hair Styling | Blossom Ewa Mazur', 'Blow-dry, waves or an occasion style for weddings and events. From 80 zł at Blossom Ewa Mazur in Gorlice.', 1, 1, '', '', NULL, 8, 'Enable', NOW(), NOW());
INSERT INTO `services` (`service_id`, `service_category_id`, `service_name`, `service_slug`, `service_summary`, `service_description`, `service_price_from`, `service_price_suffix`, `service_duration_label`, `service_duration_minutes`, `service_card_image`, `service_hero_image`, `service_included`, `service_before_visit`, `service_aftercare`, `service_featured`, `service_show_shapes`, `page_title`, `meta_description`, `robots_index`, `robots_follow`, `og_title`, `og_description`, `og_image`, `service_order`, `service_status`, `service_added`, `service_updated`) VALUES (9, 2, 'Hair Colour', 'hair-color', 'Full colour, root touch-ups and grey coverage.', '<p>Colour matched in daylight and applied with your regrowth in mind, so it stays wearable as it grows out.</p>', '160', '', '120 min', 120, '97855de9edb5b83acd7907627b0d29fe.jpg', '97855de9edb5b83acd7907627b0d29fe.jpg', 'Colour consultation and shade match\nApplication and development\nWash, condition and finish', 'A patch test may be needed before your appointment — we will confirm when you book', '', 0, 0, 'Hair Colour | Blossom Ewa Mazur', 'Full colour, root touch-ups and grey coverage. From 160 zł at Blossom Ewa Mazur in Gorlice.', 1, 1, '', '', NULL, 9, 'Enable', NOW(), NOW());
INSERT INTO `services` (`service_id`, `service_category_id`, `service_name`, `service_slug`, `service_summary`, `service_description`, `service_price_from`, `service_price_suffix`, `service_duration_label`, `service_duration_minutes`, `service_card_image`, `service_hero_image`, `service_included`, `service_before_visit`, `service_aftercare`, `service_featured`, `service_show_shapes`, `page_title`, `meta_description`, `robots_index`, `robots_follow`, `og_title`, `og_description`, `og_image`, `service_order`, `service_status`, `service_added`, `service_updated`) VALUES (10, 2, 'Hair Treatments', 'hair-treatments', 'Conditioning and scalp treatments for dry or tired hair.', '<p>A treatment chosen after we look at your hair and scalp, added to a cut or booked on its own.</p>', '70', '', '40 min', 40, 'dfe5cbd36483eb4bbd49abd88080efa1.jpg', 'dfe5cbd36483eb4bbd49abd88080efa1.jpg', 'Hair and scalp assessment\nTreatment application\nFinish', '', '', 0, 0, 'Hair Treatments | Blossom Ewa Mazur', 'Conditioning and scalp treatments for dry or tired hair. From 70 zł at Blossom Ewa Mazur in Gorlice.', 1, 1, '', '', NULL, 10, 'Enable', NOW(), NOW());
INSERT INTO `services` (`service_id`, `service_category_id`, `service_name`, `service_slug`, `service_summary`, `service_description`, `service_price_from`, `service_price_suffix`, `service_duration_label`, `service_duration_minutes`, `service_card_image`, `service_hero_image`, `service_included`, `service_before_visit`, `service_aftercare`, `service_featured`, `service_show_shapes`, `page_title`, `meta_description`, `robots_index`, `robots_follow`, `og_title`, `og_description`, `og_image`, `service_order`, `service_status`, `service_added`, `service_updated`) VALUES (11, 3, 'Facial & Skin Care', 'facial-skin-care', 'Facials chosen to suit your skin, with no rushing.', '<p>We look at your skin first and pick the treatment from there. Expect an unhurried hour and straightforward advice rather than a product list.</p>', '120', '', '60 min', 60, 'f8fb0fa080449073cd6cbf8a6ca206e9.jpg', 'f8fb0fa080449073cd6cbf8a6ca206e9.jpg', 'Skin consultation\nCleanse, exfoliate and treatment mask\nMassage and finishing care', 'Come without makeup if that suits your day', 'Keep sun exposure gentle for a day or two afterwards', 0, 0, 'Facial & Skin Care | Blossom Ewa Mazur', 'Facials chosen to suit your skin, with no rushing. From 120 zł at Blossom Ewa Mazur in Gorlice.', 1, 1, '', '', NULL, 11, 'Enable', NOW(), NOW());
INSERT INTO `services` (`service_id`, `service_category_id`, `service_name`, `service_slug`, `service_summary`, `service_description`, `service_price_from`, `service_price_suffix`, `service_duration_label`, `service_duration_minutes`, `service_card_image`, `service_hero_image`, `service_included`, `service_before_visit`, `service_aftercare`, `service_featured`, `service_show_shapes`, `page_title`, `meta_description`, `robots_index`, `robots_follow`, `og_title`, `og_description`, `og_image`, `service_order`, `service_status`, `service_added`, `service_updated`) VALUES (12, 3, 'Makeup', 'makeup', 'Makeup for weddings, events and photographs.', '<p>Shade-matched in daylight and built to last the length of the day, whether that is a ceremony or a evening out.</p>', '150', '', '60 min', 60, '9d3d5916b4ee67ad8bec21af38d72b3a.jpg', '9d3d5916b4ee67ad8bec21af38d72b3a.jpg', 'Shade matching\nFull application\nTouch-up advice', 'Arrive with clean, moisturised skin', '', 0, 0, 'Makeup | Blossom Ewa Mazur', 'Makeup for weddings, events and photographs. From 150 zł at Blossom Ewa Mazur in Gorlice.', 1, 1, '', '', NULL, 12, 'Enable', NOW(), NOW());
INSERT INTO `services` (`service_id`, `service_category_id`, `service_name`, `service_slug`, `service_summary`, `service_description`, `service_price_from`, `service_price_suffix`, `service_duration_label`, `service_duration_minutes`, `service_card_image`, `service_hero_image`, `service_included`, `service_before_visit`, `service_aftercare`, `service_featured`, `service_show_shapes`, `page_title`, `meta_description`, `robots_index`, `robots_follow`, `og_title`, `og_description`, `og_image`, `service_order`, `service_status`, `service_added`, `service_updated`) VALUES (13, 3, 'Waxing & Hair Removal', 'waxing', 'Brow shaping, facial and body waxing.', '<p>Quick, careful and private. Brow shaping is the one most often added to a nail appointment.</p>', '60', '', '30 min', 30, 'ac1dbfadb18c12360a0d5e71fb850eb6.jpg', 'ac1dbfadb18c12360a0d5e71fb850eb6.jpg', 'Consultation on shape\nWaxing\nSoothing aftercare', '', 'Skip heat, swimming and sunbeds for 24 hours', 0, 0, 'Waxing & Hair Removal | Blossom Ewa Mazur', 'Brow shaping, facial and body waxing. From 60 zł at Blossom Ewa Mazur in Gorlice.', 1, 1, '', '', NULL, 13, 'Enable', NOW(), NOW());
INSERT INTO `services` (`service_id`, `service_category_id`, `service_name`, `service_slug`, `service_summary`, `service_description`, `service_price_from`, `service_price_suffix`, `service_duration_label`, `service_duration_minutes`, `service_card_image`, `service_hero_image`, `service_included`, `service_before_visit`, `service_aftercare`, `service_featured`, `service_show_shapes`, `page_title`, `meta_description`, `robots_index`, `robots_follow`, `og_title`, `og_description`, `og_image`, `service_order`, `service_status`, `service_added`, `service_updated`) VALUES (14, 3, 'Beauty Treatments', 'beauty-treatments', 'Brow tinting, lashes and other finishing touches.', '<p>The smaller treatments that tend to get booked alongside something else — brows, lashes and general tidying up before an event.</p>', '50', '', '30 min', 30, 'b3bd52b297d21bb462b2d694f1b95478.jpg', 'b3bd52b297d21bb462b2d694f1b95478.jpg', 'Consultation\nTreatment\nAftercare advice', '', '', 0, 0, 'Beauty Treatments | Blossom Ewa Mazur', 'Brow tinting, lashes and other finishing touches. From 50 zł at Blossom Ewa Mazur in Gorlice.', 1, 1, '', '', NULL, 14, 'Enable', NOW(), NOW());
