-- Nail Shapes & Finishes (Manage > Miscellaneous Contents) --------------------

SELECT 'nail_shapes_finishes', 'Nail Shapes & Finishes', 'Enable'
WHERE NOT EXISTS (
    SELECT 1 FROM `miscellaneous_content_sections` WHERE `section_key` = 'nail_shapes_finishes'
);


-- Services listing page (Web Pages > Services) ---------------------------------

UPDATE `pages` SET
    `banner_title` = 'Our services',
    `banner_heading` = 'Everything we do, and what it costs',
    `banner_text` = 'Nails lead the list — manicure, gel, art, extensions and care. Hair, skin, makeup and waxing follow, and any of them can be booked together in one visit.',
    `banner_background` = 'fced6be36ba3a0eb9a7d389a9e4d5346.jpg',
    `meta_description` = 'Manicure, gel nails, nail art, extensions and nail care at Blossom in Gorlice, alongside hair, facials, makeup and waxing. Prices and durations for every service.'
WHERE `page_id` = 37;


-- Service Page labels (Manage > Miscellaneous Contents) ------------------------

SELECT 'service_page', 'Service Page', 'Enable'
WHERE NOT EXISTS (SELECT 1 FROM `miscellaneous_content_sections` WHERE `section_key` = 'service_page');

